{"command": "# P0-1: Re-run the FULL credential status endpoint (different from deploy-tools)
# This one actually performs live authenticated tests
curl -s --max-time 30 https://api.ivxholding.com/api/ivx/owner-credential-status 2>&1 | python3 -c "
import sys, json
try:
    d = json.load(sys.stdin)
    rows = d.get('rows', d.get('credentials', []))
    if not rows:
        print('No rows found. Keys:', list(d.keys()))
        print(json.dumps(d, indent=2)[:2000])
    else:
        for r in rows:
            n = r.get('name', r.get('variable', ''))
            s = r.get('status', '')
            v = r.get('verificationResult', '')
            h = r.get('httpStatus', '')
            b = r.get('blocker', '')
            if 'SUPABASE' in n.upper() or 'SERVICE' in n.upper():
                print(f'{n}: status={s} httpStatus={h} verification={v} blocker={b}')
except Exception as e:
    print(f'Error: {e}')
    print(sys.stdin.read()[:500])
" 2>&1"}

